# v107: köztársaság kori éremkincsek (CHRR Online) az „Éremkincsek” kártya végén. Adat: chrr/calc.py -> chrr/data.json
import json
D=json.load(open('chrr/data.json'));B=D['bins']
BANDS=[(-91,-82),(-80,-71),(-49,-42),(-32,-30)]
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    d1=lambda x:(f'{x:.1f}'.replace('.',',') if H else f'{x:.1f}')
    def yl(y): return (f'Kr. e. {-y}' if y<0 else ('0' if y==0 else f'Kr. u. {y}')) if H else (f'{-y} BC' if y<0 else ('0' if y==0 else f'AD {y}'))
    def pl(a,b):
        if H: return (f'Kr. e. {-a}–{-b}' if b<0 else f'Kr. e. {-a} – Kr. u. {b}')
        return (f'{-a}–{-b} BC' if b<0 else f'{-a} BC – AD {b}')
    o=[]
    o.append('      <h3 class="aqh">'+T('Előzmény: a köztársaság kori éremkincsek','Before the empire: coin hoards of the Republic')+'</h3>')
    o.append('      <p class="hint">'+T('A CHRE a császárkorral kezdődik. A köztársaság utolsó másfél századára egy másik adatbázis, a Coin Hoards of the Roman Republic (CHRR) ad képet: %d arany- és ezüstkincset tart számon, ebből %d-nek ismert a záró éve, vagyis a legkésőbbi érméjének verési éve. A keltezett kincsek mediánja %s érme.'%(D['n'],D['dated'],d1(D['coins']['median'])),'The CHRE begins with the empire. For the last century and a half of the Republic another database, the Coin Hoards of the Roman Republic (CHRR), gives the picture: it records %d gold and silver hoards, %d of them with a known closing year, that is, the year in which their latest coin was struck. The median of the dated hoards is %s coins.'%(D['n'],D['dated'],d1(D['coins']['median'])))+'</p>')
    X0,X1=-150,20;Wd,Ht,L,R,Tp,Bt=860,290,40,12,22,40;pw=Wd-L-R;ph=Ht-Tp-Bt;ymax=70;bw=pw/len(B)
    xx=lambda y:L+(y-X0)/(X1-X0)*pw
    s=['      <svg class="chrrsvg" viewBox="0 0 %d %d" role="img" aria-label="%s">'%(Wd,Ht,T('Köztársaság kori éremkincsek száma ötévenként a záró év szerint','Number of Republican coin hoards per five years by closing year'))]
    for k,(a,b) in zip('ABCD',BANDS): s.append('<rect class="bd" x="%.1f" y="%d" width="%.1f" height="%d"/><text class="ax bl" x="%.1f" y="%d" text-anchor="middle">%s</text>'%(xx(a),Tp,xx(b+1)-xx(a),ph,(xx(a)+xx(b+1))/2,Tp-6,k))
    for v in (0,20,40,60): yy=Tp+ph-ph*v/ymax;s.append('<line class="gr" x1="%d" x2="%d" y1="%.1f" y2="%.1f"/><text class="ax" x="%d" y="%.1f" text-anchor="end">%d</text>'%(L,Wd-R,yy,yy,L-6,yy+5,v))
    for i,b in enumerate(B):
        x=L+i*bw;h1=ph*D['all'][i]/ymax;h2=ph*D['it'][i]/ymax
        s.append('<rect class="b1" x="%.1f" y="%.1f" width="%.1f" height="%.1f"><title>%s: %d / %d</title></rect>'%(x+1,Tp+ph-h1,bw-2,h1,yl(b),D['all'][i],D['it'][i]))
        s.append('<rect class="b2" x="%.1f" y="%.1f" width="%.1f" height="%.1f"/>'%(x+bw*0.22,Tp+ph-h2,bw*0.56,h2))
    for y in range(-150,21,10):
        s.append('<line class="tk" x1="%.1f" x2="%.1f" y1="%d" y2="%d"/>'%(xx(y),xx(y),Tp+ph,Tp+ph+5))
        if y%50==0: s.append('<text class="ax" x="%.1f" y="%d" text-anchor="%s">%s</text>'%(xx(y),Tp+ph+22,'start' if y==-150 else 'middle',yl(y)))
    s.append('</svg>');o.append(''.join(s))
    o.append('      <p class="hint aqleg"><span class="sw chb1"></span> '+T('minden keltezett kincs (%d; a diagramon a Kr. e. 150 utániak, %d korábbi nincs rajta) · '%(D['dated'],D['before']),'all dated hoards (%d; the chart shows those after 150 BC, %d earlier ones are not on it) · '%(D['dated'],D['before']))+'<span class="sw chb2"></span> '+T('ebből Itália a szigetekkel (%d). A halvány sávok: <b>A</b> a szövetséges háború és Sulla polgárháborúja (Kr. e. 91–82) · <b>B</b> Sertorius háborúja Hispaniában és Spartacus felkelése (80–71) · <b>C</b> Caesar polgárháborúja, meggyilkolása és Philippi (49–42) · <b>D</b> Actium (31).'%D['nreg']['it'],'of which Italy with the islands (%d). The pale bands: <b>A</b> the Social War and Sulla’s civil war (91–82 BC) · <b>B</b> the war of Sertorius in Spain and the revolt of Spartacus (80–71) · <b>C</b> Caesar’s civil war, his murder and Philippi (49–42) · <b>D</b> Actium (31).'%D['nreg']['it'])+'</p>')
    SRC=T('K. Lockyear, <i>Coin Hoards of the Roman Republic Online</i>, American Numismatic Society, numismatics.org/chrr (Open Database License); saját számítás. A történeti megfeleltetés saját.','K. Lockyear, <i>Coin Hoards of the Roman Republic Online</i>, American Numismatic Society, numismatics.org/chrr (Open Database License); own calculation. The historical links are our own.')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <div class="regwrap"><table class="regtab chrrtab">')
    o.append('        <thead><tr><th>'+T('Időszak','Period')+'</th><th>'+T('Kincs','Hoards')+'</th><th>'+T('Évente','Per year')+'</th><th>'+T('Itália','Italy')+'</th><th>Hispania</th><th>'+T('Dacia (a mai Románia)','Dacia (modern Romania)')+'</th><th>'+T('Máshol','Elsewhere')+'</th></tr></thead>')
    o.append('        <tbody>')
    for p in D['per']:
        o.append('          <tr><td>'+pl(p['a'],p['b'])+'</td><td>%d</td><td>%s</td><td>%d</td><td>%d</td><td>%d</td><td>%d</td></tr>'%(p['all'],d1(p['peryear']),p['it'],p['hi'],p['ro'],p['ot']))
    o.append('        </tbody>')
    o.append('        <tfoot><tr><td>'+T('Együtt','Total')+'</td><td>%d</td><td></td><td>%d</td><td>%d</td><td>%d</td><td>%d</td></tr></tfoot>'%(D['dated'],D['nreg']['it'],D['nreg']['hi'],D['nreg']['ro'],D['nreg']['ot']))
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    P=D['per']
    o.append('      <p class="hint">'+T('Békeidőben évente egy-két kincs maradt a földben, a polgárháborúk alatt ennek a többszöröse: Kr. e. 81–71 között évi %s, 49–42 között évi %s. A kincset az rejti el, aki fél, és az hagyja ott, aki nem tér vissza érte, ezért a csúcsok a háborús veszteséget mutatják, nem a gazdagságot. A legtöbb kincs záró éve Kr. e. 74 (%d), 42 (%d) és 46 (%d).'%(d1(P[2]['peryear']),d1(P[4]['peryear']),D['top'][0][1],D['top'][1][1],D['top'][2][1]),'In peacetime one or two hoards a year stayed in the ground, during the civil wars several times as many: %s a year in 81–71 BC, %s a year in 49–42. A hoard is hidden by someone who is afraid and left by someone who does not come back for it, so the peaks show the losses of war, not wealth. The most frequent closing years are 74 BC (%d), 42 (%d) and 46 (%d).'%(d1(P[2]['peryear']),d1(P[4]['peryear']),D['top'][0][1],D['top'][1][1],D['top'][2][1]))+'</p>')
    o.append('      <p class="hint">'+T('<b>Mire kell vigyázni.</b> A záró év a legkésőbbi érme verési éve, a kincset ennél később is elrejthették. Ha egy évben sok pénzt vertek, több kincs „zárul” azzal az évvel, ezért a diagram ötéves sávokat mutat, nem éveket. A Dacia területén talált %d kincs a birodalmon kívülre került dénárokból áll, ezek csúcsai nem feltétlenül a római belháborúkat tükrözik. Magából Rómából az adatbázis négy kincset ismer; kettőnek van záró éve: az egyik 121 dénár és 2 victoriatus (Kr. e. 147), a másik 16 dénár a Largo di Torre Argentináról (Kr. e. 97).'%D['nreg']['ro'],'<b>What to watch for.</b> The closing year is the year the latest coin was struck; the hoard may have been hidden later. If much money was struck in one year, more hoards “close” with that year, so the chart shows five-year bands, not years. The %d hoards found in the territory of Dacia consist of denarii that had left the empire; their peaks do not necessarily reflect the Roman civil wars. From Rome itself the database knows four hoards; two have a closing year: one of 121 denarii and 2 victoriati (147 BC), the other of 16 denarii from Largo di Torre Argentina (97 BC).'%D['nreg']['ro'])+'</p>')
    o.append('      <p class="hint">'+T('A Kr. e. 80–71 közötti csúcs ugyanarra az évtizedre esik, amelyben a grönlandi jég szerint az ólomkibocsátás, vagyis az ezüstbányászat a köztársaság kori mélypontjára süllyedt (lásd „Hajóroncsok és ólomszennyezés”). Ez Sertorius hispaniai háborújának és Spartacus felkelésének évtizede; Hispaniából a megelőző tíz évből egyetlen kincs sincs, ebből az évtizedből %d.'%(P[2]['hi'])+'','The peak of 80–71 BC falls in the same decade in which, according to the Greenland ice, lead emissions, that is, silver mining, sank to their Republican minimum (see “Shipwrecks and lead pollution”). This is the decade of the war of Sertorius in Spain and of the revolt of Spartacus; from Spain there is not a single hoard from the preceding ten years, and %d from this decade.'%(P[2]['hi'])+'')+'</p>')
    return '\n'.join(o)+'\n'
SRCLI=lambda l:('      <li><b>Köztársaság kori éremkincsek.</b> K. Lockyear: <i>Coin Hoards of the Roman Republic Online</i>, American Numismatic Society (<a href="https://numismatics.org/chrr/">numismatics.org/chrr</a>), Open Database License (ODbL 1.0); a teljes kincslista letöltve, a számítások sajátok.</li>' if l=='hu' else '      <li><b>Coin hoards of the Republic.</b> K. Lockyear: <i>Coin Hoards of the Roman Republic Online</i>, American Numismatic Society (<a href="https://numismatics.org/chrr/">numismatics.org/chrr</a>), Open Database License (ODbL 1.0); the full list of hoards was downloaded, the calculations are our own.</li>')
